curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if 'Maya' in u.get('real_name','') or 'Chen' in u.get('real_name',''):
            print(u['id'], u['real_name'])
else:
    print('Error:', data)
"

curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=D_MAYA&limit=999" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data.get('messages', []):
        text = msg.get('text', '')
        if 'Q3 launch checklist is ready for review' in text:
            print('FOUND:', msg['ts'], text)
    # Also print all messages for debugging
    print('---ALL MESSAGES---')
    for msg in data.get('messages', []):
        print(msg['ts'], msg.get('text','')[:100])
else:
    print('Error:', data)
"
